// ASYNC

export const getPostProcessor = (
		purpose: string,
		fileName: (string | undefined) = undef
		): (TPostProcessor | undefined) => {

	const pp = hConfig.hPostProcessors[purpose]
	if (defined(pp)) {
		return pp
	}
	else {
		DBG(`No post processor for ${purpose} files`)
		return undef
	}
}

